stylesInObservedDomOrder.relevantCSS:
@media(max-width:820px){#gbm-mobile-shell{background:linear-gradient(180deg,#0021a5,#0a1a6b)!important;border:0!important;box-shadow:inset 0 -3px 0 #fa4616,0 4px 14px #ff6a2b59!important}
#gbm-mobile-shell .gbm-ms-logo{position:relative;display:flex!important;align-items:center;min-height:44px;width:auto;min-width:0;flex:0 1 auto;line-height:1!important;font:italic 900 30px/1 "Barlow Condensed",Barlow,sans-serif;letter-spacing:-.01em;text-transform:uppercase;color:#fff!important;-webkit-text-fill-color:#fff;text-decoration:none!important;white-space:nowrap}
#gbm-mobile-shell .gbm-ms-logo img,#gbm-mobile-drawer-root .gbm-ms-head img{position:absolute!important;width:1px!important;height:1px!important;opacity:0;pointer-events:none}
#gbm-mobile-shell .gbm-ms-logo:before,#gbm-mobile-drawer-root .gbm-ms-head a:before{content:"Gator"}
#gbm-mobile-shell .gbm-ms-logo:after,#gbm-mobile-drawer-root .gbm-ms-head a:after{content:"Bait";color:#ff6a3d;-webkit-text-fill-color:#ff6a3d}
#gbm-mobile-shell .gbm-ms-trigger{flex:none;width:auto;min-width:72px;height:44px;min-height:44px;padding:0 10px;border:2px solid #ffffff59!important;border-radius:0!important;background:transparent!important;color:#fff!important;font:800 14px/1 "Barlow Condensed",Barlow,sans-serif!important;letter-spacing:.1em}
#gbm-mobile-shell .gbm-ms-bars i{background:#ff6a3d!important}
#gbm-mobile-shell .gbm-ms-shop{flex:none;margin:0 8px 0 auto;display:inline-flex;align-items:center;justify-content:center;gap:4px;height:44px;min-height:44px;padding:0 12px;background:#fa4616;color:#08132f!important;-webkit-text-fill-color:#08132f;font:italic 800 16px/1 "Barlow Condensed",Barlow,sans-serif;letter-spacing:.06em;text-transform:uppercase;text-decoration:none!important;white-space:nowrap;clip-path:polygon(8px 0,100% 0,calc(100% - 8px) 100%,0 100%)}
#gbm-mobile-drawer-root .gbm-ms-panel{background:linear-gradient(180deg,#0a1a6b,#040c30)!important}
#gbm-mobile-drawer-root .gbm-ms-head{border:0!important;box-shadow:inset 0 -3px 0 #fa4616}
#gbm-mobile-drawer-root .gbm-ms-head a{position:relative;color:#fff!important;-webkit-text-fill-color:#fff;text-decoration:none!important;font:italic 900 28px/1 "Barlow Condensed",Barlow,sans-serif;text-transform:uppercase}
#gbm-mobile-drawer-root .gbm-ms-close{background:transparent!important;color:#fff!important;border-color:#ffffff59!important;width:44px!important;height:44px!important}
#gbm-mobile-drawer-root .gbm-ms-nav a{background:transparent!important;color:#fff!important;-webkit-text-fill-color:#fff!important;border-bottom-color:#ffffff1f!important;font:700 19px/1.1 "Barlow Condensed",Barlow,sans-serif!important;letter-spacing:.06em;text-transform:uppercase}
#gbm-mobile-drawer-root .gbm-ms-nav a[aria-current=page]{background:#ffffff0f!important;border-left:4px solid #fa4616!important;color:#ffb39a!important;-webkit-text-fill-color:#ffb39a!important}
#gbm-mobile-drawer-root .gbm-ms-nav a.gbm-ms-shop{gap:6px;white-space:nowrap;font-size:17px!important;margin:12px 16px 4px;width:calc(100% - 32px);min-height:48px;justify-content:center;border:0;background:#fa4616!important;color:#08132f!important;-webkit-text-fill-color:#08132f!important;clip-path:polygon(10px 0,100% 0,calc(100% - 10px) 100%,0 100%)}
#gbm-mobile-drawer-root .gbm-ms-nav a.gbm-ms-join{margin:6px 16px 8px;width:calc(100% - 32px);justify-content:center;border:0;border-radius:0!important;background:#fff!important;color:#0a1a6b!important;-webkit-text-fill-color:#0a1a6b!important;clip-path:polygon(10px 0,100% 0,calc(100% - 10px) 100%,0 100%)}
#gbm-mobile-drawer-root .gbm-ms-foot{color:#c3cdff!important}
#gbm-mobile-drawer-root .gbm-ms-foot a{color:#ffb39a!important;-webkit-text-fill-color:#ffb39a!important}}
@media(max-width:430px){#gbm-mobile-shell .gbm-ms-logo{font-size:25px}#gbm-mobile-shell .gbm-ms-shop{padding:0 10px;margin-right:6px}#gbm-mobile-shell .gbm-ms-trigger{min-width:0;padding:0 8px}}
@media(max-width:374px){#gbm-mobile-shell .gbm-ms-shop .gbm-x{display:none}#gbm-mobile-shell .gbm-ms-logo{font-size:23px}}

#gbm-mobile-shell,#gbm-mobile-drawer-root{display:none}
@media(max-width:820px){#gbm-mobile-shell-host{position:sticky;top:0;z-index:2147481500;height:60px}
#gbm-mobile-shell{display:flex;position:relative;top:0;z-index:2147481500;height:60px;padding:7px 10px;box-sizing:border-box;align-items:center;justify-content:space-between;background:#fff;border-top:4px solid #fa4616;border-bottom:1px solid #dfe4ec;box-shadow:0 3px 12px #08132f14}
#gbm-mobile-shell .gbm-ms-logo{display:block;width:min(180px,52vw);line-height:0}
#gbm-mobile-shell .gbm-ms-logo img{display:block;width:100%;height:auto;max-height:44px;object-fit:contain}
#gbm-mobile-shell .gbm-ms-trigger{border:1px solid #b8c1d0;background:#fff;color:#08132f;width:72px;height:40px;border-radius:4px;display:flex;align-items:center;justify-content:center;gap:7px;font:900 11px/1 Barlow,sans-serif;letter-spacing:.08em;text-transform:uppercase}
#gbm-mobile-shell .gbm-ms-bars{width:16px;height:12px;display:grid;align-content:space-between}
#gbm-mobile-shell .gbm-ms-bars i{display:block;height:2px;background:#0021a5}
#gbm-mobile-drawer-root{display:block;position:fixed;inset:0;overflow:hidden;z-index:2147482500;pointer-events:none;font-family:Barlow,sans-serif}
#gbm-mobile-drawer-root .gbm-ms-backdrop{position:absolute;inset:0;background:#08132f8f;opacity:0}
#gbm-mobile-drawer-root .gbm-ms-panel{position:absolute;top:0;right:0;width:min(88vw,350px);height:100dvh;background:#fff;transform:translateX(104%);display:flex;flex-direction:column;overflow:auto;box-shadow:-18px 0 48px #08132f38}
html.gbm-mobile-menu-open #gbm-mobile-drawer-root{pointer-events:auto}
html.gbm-mobile-menu-open #gbm-mobile-drawer-root .gbm-ms-backdrop{opacity:1}
html.gbm-mobile-menu-open #gbm-mobile-drawer-root .gbm-ms-panel{transform:translateX(0)}
.gbm-ms-head{min-height:66px;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;border-top:4px solid #fa4616;border-bottom:1px solid #dfe4ec}
.gbm-ms-head img{display:block;width:158px;height:auto}
.gbm-ms-close{width:40px;height:40px;border:1px solid #bcc5d2;background:#fff;color:#08132f;border-radius:50%;font:400 27px/1 Barlow}
.gbm-ms-nav{display:grid;padding-top:6px}
.gbm-ms-nav a{display:flex;align-items:center;min-height:48px;padding:0 20px;box-sizing:border-box;border-bottom:1px solid #e4e8ef;background:#fff;color:#08132f!important;-webkit-text-fill-color:#08132f!important;text-decoration:none!important;font:800 15px/1.15 Barlow,sans-serif}
.gbm-ms-nav a[aria-current="page"]{border-left:4px solid #fa4616;padding-left:16px;background:#f4f6f9}
.gbm-ms-nav .gbm-ms-join{margin:10px 16px 4px;width:calc(100% - 32px);min-height:44px;background:#fa4616;justify-content:center;border-radius:5px;text-transform:uppercase}
.gbm-ms-foot{margin-top:auto;padding:16px 20px 22px;color:#667085;font-size:11px;line-height:1.45}
.gbm-ms-foot a{color:#0021a5!important;-webkit-text-fill-color:#0021a5!important}}
